import{a as e}from"./index-CI4H9RsL.js";import{L as t}from"./LegalPage-6sS9j2Fb.js";const o={title:"Privacy Policy",updated:"Last updated: September 2026",keywords:["BrightFritexium privacy policy","data protection Australia"],sections:[{h:"1. Who we are",p:'BrightFritexium ("we", "us") operates the website brightfritexium.io and the digital wealth services described on it. For the purposes of the Australian Privacy Act 1988 (Cth), we are the data controller of the personal information described in this policy.'},{h:"2. Information we collect",p:"We collect information you give us directly, plus limited technical data needed to run the site safely:",items:["Contact and identity details: first name, last name, email address and phone number submitted through our registration form.","Verification details: government-issued ID and proof of address, processed when you complete identity verification.","Technical data: IP address, browser type, approximate location and pages visited, used to keep the platform secure.","Cookie data: small files described in section 6, used for site function and improvement."]},{h:"3. How we use your information",p:"We use your information to process registration requests, verify your identity, respond to enquiries, secure the platform against fraud, and - with your consent - send you updates about your account and our services. We never sell your personal data."},{h:"4. Legal bases",p:"We process your data on the following lawful grounds: performance of a contract (opening and running your account), legal obligation (identity checks and anti-money-laundering rules), legitimate interest (securing the platform and improving our service) and consent (marketing communications, which you can withdraw at any time)."},{h:"5. Who we share information with",p:"We share your information only with service providers who help us operate - identity verification partners, custodians, payment processors and email providers - each bound by contract to protect your data. We disclose information to authorities only where the law requires it."},{h:"6. Cookies",p:"We use essential cookies to keep the site working and optional analytics cookies to understand how it is used. You can accept or decline analytics cookies through the consent banner, and clear or block cookies through your browser settings at any time."},{h:"7. Data retention",p:"We keep your information only as long as needed for the purposes above, or as long as the law requires. Verification records are retained in line with anti-money-laundering rules; marketing data is removed when you withdraw consent."},{h:"8. Your rights",p:"Under the Australian Privacy Act you may request access to, correction of, or deletion of your personal data, object to or restrict certain processing, and ask for a portable copy. To exercise any of these rights, email support@brightfritexium.io. You may also complain to the Office of the Australian Information Commissioner (oaic.gov.au)."},{h:"9. Changes to this policy",p:"We update this policy from time to time. Material changes will be announced on this page with a revised date, and where required, notified to you directly."}]};function r(){return e(t,{content:o,path:"/privacy-policy"})}export{r as default};
